Section Rot90cw.
Context {fx : FPState} {AL : AllocLayout} {CL : CallocLayout} {ASR : AllocSure}.
Context {PINS : @LeptPins AL LL16} {P16 : O23Pins}.
#[local] Notation "'u'" := bv_unsigned (only parsing).

Section Segs.
  Variable rom : word -> option byte.

  (* [comment removed for export] *)
  Lemma cw_S : forall regs m (s wd hd wpld : Z),
    (128 <= s)%Z -> (s < 2 ^ 64)%Z -> (1 <= wd < 2 ^ 31)%Z -> (1 <= hd < 2 ^ 31)%Z -> (1 <= wpld < 2 ^ 25)%Z ->
    rdn SEGS m (Z_to_bv 64 (s - 60)) 4 = Some (word_to_le_bytes 4 (Z_to_bv 64 wd)) ->
    rdn SEGS m (Z_to_bv 64 (s - 64)) 4 = Some (word_to_le_bytes 4 (Z_to_bv 64 hd)) ->
    getr regs 2 = Z_to_bv 64 (s - 80) -> getr regs 10 = Z_to_bv 64 wpld ->
    exists regs',
      msteps SEGS (mkst regs (0x87958 : word) m rom) (mkst regs' (0x879f8 : word) m rom)
      /\ getr regs' 6 = Z_to_bv 64 wd /\ getr regs' 11 = Z_to_bv 64 0 /\ getr regs' 12 = Z_to_bv 64 0 /\ getr regs' 13 = Z_to_bv 64 hd
      /\ getr regs' 5 = Z_to_bv 64 (128 * wpld) /\ getr regs' 10 = Z_to_bv 64 (4 * wpld) /\ getr regs' 14 = Z_to_bv 64 32
      /\ getr regs' 16 = Z_to_bv 64 (hd / 32) /\ getr regs' 17 = Z_to_bv 64 (32 * (hd / 32)) /\ getr regs' 7 = Z_to_bv 64 hd
