  (* [comment removed for export] *)
  Lemma cw_Jt : forall regs m (wd hd datas wpls datad j : Z),
    (0 <= j < wd)%Z -> (wd < 2 ^ 31)%Z -> (0 <= hd < 32)%Z -> (0 <= wpls < 2 ^ 25)%Z ->
    getr regs 11 = Z_to_bv 64 j -> getr regs 12 = Z_to_bv 64 j -> getr regs 6 = Z_to_bv 64 wd -> getr regs 18 = Z_to_bv 64 wpls ->
    getr regs 9 = Z_to_bv 64 datas -> getr regs 8 = Z_to_bv 64 datad -> getr regs 13 = Z_to_bv 64 hd -> getr regs 14 = Z_to_bv 64 32 ->
    exists regs',
      msteps SEGS (mkst regs (0x879f8 : word) m rom) (mkst regs' (0x87a7c : word) m rom)
      /\ getr regs' 28 = Z_to_bv 64 (4 * (j / 32)) /\ getr regs' 6 = Z_to_bv 64 (datas + 4 * wpls * (wd - 1 - j))
      /\ getr regs' 29 = Z_to_bv 64 datad
      /\ regs_agree (fun r => In r [6; 28; 29]%list) regs regs'.
Proof.
