  (* [comment removed for export] *)
  Lemma cw_Kz : forall regs m (lines lined wpld k : Z) (bs : list byte) (v : word),
    rdn SEGS m (Z_to_bv 64 (lines + 4 * k)) 4 = Some bs -> bytes_le_to_Z bs = bv_unsigned v -> v_lw v = Z_to_bv 64 0 ->
    (0 <= k < 2 ^ 30)%Z ->
    getr regs 7 = Z_to_bv 64 k -> getr regs 6 = Z_to_bv 64 lines -> getr regs 29 = Z_to_bv 64 lined -> getr regs 5 = Z_to_bv 64 (128 * wpld) ->
    exists regs',
      msteps SEGS (mkst regs (0x87a38 : word) m rom) (mkst regs' (0x87a30 : word) m rom)
      /\ getr regs' 29 = Z_to_bv 64 (lined + 128 * wpld)
      /\ regs_agree (fun r => In r [29; 31]%list) regs regs'.
