  Lemma cw_Knz : forall regs m (lines k : Z) (bs : list byte) (v : word),
    rdn SEGS m (Z_to_bv 64 (lines + 4 * k)) 4 = Some bs -> bytes_le_to_Z bs = bv_unsigned v -> v_lw v <> Z_to_bv 64 0 ->
    (0 <= k < 2 ^ 30)%Z ->
    getr regs 7 = Z_to_bv 64 k -> getr regs 6 = Z_to_bv 64 lines ->
    exists regs',
      msteps SEGS (mkst regs (0x87a38 : word) m rom) (mkst regs' (0x87a5c : word) m rom)
      /\ getr regs' 19 = Z_to_bv 64 0 /\ getr regs' 31 = v_lw v
      /\ regs_agree (fun r => In r [19; 31]%list) regs regs'.
Proof.
