  Lemma cw_M : forall (b : bool) regs m (lined off mm : Z) (v : word) (bt : list byte) (vt : word),
    c_lts (v_sllw (v_lw v) (Z_to_bv 64 mm)) (Z_to_bv 64 0) = b -> (0 <= lined + off < 2 ^ 64)%Z ->
    rdn SEGS m (Z_to_bv 64 (lined + off)) 4 = Some bt -> bytes_le_to_Z bt = bv_unsigned vt ->
    store_ok SEGS m (Z_to_bv 64 (lined + off)) 4 = true ->
    getr regs 31 = v_lw v -> getr regs 19 = Z_to_bv 64 mm -> getr regs 29 = Z_to_bv 64 lined -> getr regs 28 = Z_to_bv 64 off ->
    exists regs' m',
      msteps SEGS (mkst regs (0x87a5c : word) m rom) (mkst regs' (0x87a50 : word) m' rom)
      /\ (if b then exists wv : word, m' = wbytes m (Z_to_bv 64 (lined + off)) (word_to_le_bytes 4 wv) else m' = m)
      /\ regs_agree (fun r => In r [20; 21]%list) regs regs'.
Proof.
