  Lemma cw_Mx : forall regs m (mm lined wpld : Z), (mm + 1 = 32)%Z ->
    getr regs 19 = Z_to_bv 64 mm -> getr regs 29 = Z_to_bv 64 lined -> getr regs 10 = Z_to_bv 64 (4 * wpld) -> getr regs 14 = Z_to_bv 64 32 ->
    exists regs',
      msteps SEGS (mkst regs (0x87a50 : word) m rom) (mkst regs' (0x87a30 : word) m rom)
      /\ getr regs' 29 = Z_to_bv 64 (lined + 4 * wpld)
      /\ regs_agree (fun r => In r [19; 29]%list) regs regs'.
Proof.
