  Lemma cw_T : forall (b : bool) regs m (s lines i tgt hd : Z) (bs : list byte) (v : word) (bt : list byte) (vt : word),
    (128 <= s)%Z -> (s < 2 ^ 64)%Z -> (0 <= i < 2 ^ 31)%Z -> (0 <= tgt)%Z -> (tgt + 4 <= s - 80)%Z ->
    rdn SEGS m (Z_to_bv 64 (lines + 4 * (i / 32))) 4 = Some bs -> bytes_le_to_Z bs = bv_unsigned v ->
    c_eq (v_andi (v_srlw (v_lw v) (v_xori (Z_to_bv 64 i) (-1))) 1) (Z_to_bv 64 0) = b ->
    rdn SEGS m (Z_to_bv 64 tgt) 4 = Some bt -> bytes_le_to_Z bt = bv_unsigned vt ->
    store_ok SEGS m (Z_to_bv 64 tgt) 4 = true ->
    rdn SEGS m (Z_to_bv 64 (s - 64)) 4 = Some (word_to_le_bytes 4 (Z_to_bv 64 hd)) -> (0 <= hd < 2 ^ 31)%Z ->
    getr regs 2 = Z_to_bv 64 (s - 80) -> getr regs 29 = Z_to_bv 64 i -> getr regs 6 = Z_to_bv 64 lines -> getr regs 28 = Z_to_bv 64 tgt ->
    getr regs 7 = Z_to_bv 64 hd ->
    exists regs' m',
      msteps SEGS (mkst regs (0x87a9c : word) m rom) (mkst regs' (0x87a90 : word) m' rom)
      /\ (if b then m' = m else exists wv : word, m' = wbytes m (Z_to_bv 64 tgt) (word_to_le_bytes 4 wv))
      /\ getr regs' 7 = Z_to_bv 64 hd
      /\ regs_agree (fun r => In r [7; 19; 31]%list) regs regs'.
