  Lemma cw_Tn : forall regs m (i hd tgt wpld : Z), (0 <= i)%Z -> (i + 1 < hd < 2 ^ 31)%Z ->
    getr regs 29 = Z_to_bv 64 i -> getr regs 7 = Z_to_bv 64 hd -> getr regs 28 = Z_to_bv 64 tgt -> getr regs 10 = Z_to_bv 64 (4 * wpld) ->
    exists regs',
      msteps SEGS (mkst regs (0x87a90 : word) m rom) (mkst regs' (0x87a9c : word) m rom)
      /\ getr regs' 29 = Z_to_bv 64 (i + 1) /\ getr regs' 28 = Z_to_bv 64 (tgt + 4 * wpld)
      /\ regs_agree (fun r => In r [28; 29]%list) regs regs'.
