  (* [comment removed for export] *)
  Lemma cw_Rn : forall regs m (s j wd : Z), (128 <= s)%Z -> (s < 2 ^ 64)%Z -> (0 <= j)%Z -> (j + 1 < wd < 2 ^ 31)%Z ->
    rdn SEGS m (Z_to_bv 64 (s - 60)) 4 = Some (word_to_le_bytes 4 (Z_to_bv 64 wd)) ->
    getr regs 2 = Z_to_bv 64 (s - 80) -> getr regs 11 = Z_to_bv 64 j -> getr regs 12 = Z_to_bv 64 j ->
    exists regs',
      msteps SEGS (mkst regs (0x879e8 : word) m rom) (mkst regs' (0x879f8 : word) m rom)
      /\ getr regs' 11 = Z_to_bv 64 (j + 1) /\ getr regs' 12 = Z_to_bv 64 (j + 1) /\ getr regs' 6 = Z_to_bv 64 wd
